import { readFileSync } from 'node:fs';

const records = JSON.parse(readFileSync(new URL('./records.json', import.meta.url), 'utf8'));

const inputSchema = {
  type: 'object',
  properties: {
    query: { type: 'string', description: 'Search query matched case-insensitively against record names' },
    limit: { type: 'integer', minimum: 1, maximum: 4, default: 2, description: 'Maximum number of matching records to return (default 2)' }
  },
  required: ['query'],
  additionalProperties: false
};

export async function listTools() {
  return [
    {
      name: 'search_records',
      description: 'Search records by case-insensitive name match.',
      inputSchema
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'search_records') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32601;
    throw err;
  }

  // Validate arguments
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    const err = new Error('Invalid arguments: expected an object');
    err.code = -32602;
    throw err;
  }

  const extra = Object.keys(args).filter(k => k !== 'query' && k !== 'limit');
  if (extra.length) {
    const err = new Error(`Unexpected arguments: ${extra.join(', ')}`);
    err.code = -32602;
    throw err;
  }

  if (!('query' in args)) {
    const err = new Error('Missing required argument: query');
    err.code = -32602;
    throw err;
  }

  const query = args.query;
  if (typeof query !== 'string') {
    const err = new Error('query must be a string');
    err.code = -32602;
    throw err;
  }

  let limit = 2;
  if ('limit' in args) {
    limit = args.limit;
    if (!Number.isInteger(limit) || limit < 1 || limit > 4) {
      const err = new Error('limit must be an integer between 1 and 4');
      err.code = -32602;
      throw err;
    }
  }

  const q = query.toLowerCase();
  const matching = records.filter(r => r.name.toLowerCase().includes(q));
  const results = matching.slice(0, limit);

  return {
    content: [{ type: 'text', text: JSON.stringify({ records: results }) }]
  };
}
